// Browser storage, done once and done carefully.
//
// ── what this is, and what it is not ─────────────────────────────────────
// This is DEMO persistence. It exists so the CMS can be shown to a client
// before the content worker is deployed, and it is deliberately the only
// place in the codebase that touches localStorage for CMS data. Everything
// above it talks to an adapter and cannot tell the difference, which is the
// whole point: when the real backend lands, one toggle changes and none of the
// UI moves.
//
// It is NOT shared storage. Data written here lives in one browser on one
// machine, is invisible to a colleague, and is gone with the site data. The
// interface says so in one line rather than pretending otherwise.
//
// ── why every call is guarded ────────────────────────────────────────────
// Four things go wrong with localStorage and all four are ordinary:
//
//   1. There is no `window` at all. Gatsby renders these pages in Node at
//      build time, so an unguarded read breaks the BUILD, not just a browser.
//   2. Access throws. Safari in private mode and "block all cookies" both make
//      the getter itself raise, so `typeof localStorage` is not enough — the
//      access has to be inside a try.
//   3. The value is not what we wrote. Someone edited it, a previous version
//      wrote a different shape, or it is simply truncated.
//   4. The write fails. Quota exceeded, most often, which is why nothing here
//      is used for images.
//
// A caller gets `null` for a bad read and an explicit failure for a bad write.
// Nothing here throws, and nothing here silently swallows a write failure —
// reporting a save that did not happen is the one outcome worse than failing.

/** Every key this project owns, in one place. Convention: kr:<area>:<thing>. */
export const STORAGE_KEYS = {
  /** The Application Builder document. */
  applications: "kr:applications:v1",
  /** Properties created or edited in the CMS, by slug. */
  properties: "kr:properties:v1",
  /** The in-progress wizard draft, so a refresh mid-workflow recovers. */
  propertyDraft: "kr:property-draft:v1",
} as const;

export type StorageKey = (typeof STORAGE_KEYS)[keyof typeof STORAGE_KEYS];

export type WriteResult =
  | { ok: true }
  | { ok: false; reason: string };

/**
 * Whether browser storage can actually be used right now.
 *
 * Probed with a real write rather than a feature check, because the failure
 * modes that matter (private browsing, blocked cookies) present as a working
 * object that throws on use.
 */
export function isStorageAvailable(): boolean {
  try {
    if (typeof window === "undefined" || !window.localStorage) return false;

    const probe = "kr:__probe__";
    window.localStorage.setItem(probe, "1");
    window.localStorage.removeItem(probe);
    return true;
  } catch {
    return false;
  }
}

/**
 * Reads and parses a stored value.
 *
 * Returns null for every failure — absent, unreadable, unparseable — because
 * to the caller they mean the same thing: there is nothing usable here, use
 * your seed. `validate` is what stops a stale or hand-edited shape being
 * handed to the UI as if it were current.
 */
export function readJson<T>(
  key: StorageKey,
  validate: (value: unknown) => T | null
): T | null {
  if (typeof window === "undefined") return null;

  let raw: string | null = null;

  try {
    raw = window.localStorage.getItem(key);
  } catch {
    return null;
  }

  if (!raw) return null;

  let parsed: unknown;

  try {
    parsed = JSON.parse(raw);
  } catch {
    /* Corrupt. Left in place rather than deleted: a developer looking into a
       bug report can still see what was there, and the caller has already
       fallen back to its seed. */
    return null;
  }

  try {
    return validate(parsed);
  } catch {
    return null;
  }
}

/**
 * Writes a value, and says so when it could not.
 *
 * The reason is written for the person using the CMS, not for a console. They
 * cannot act on "QuotaExceededError", but they can act on being told the
 * change is not saved.
 */
export function writeJson(key: StorageKey, value: unknown): WriteResult {
  if (typeof window === "undefined") {
    return { ok: false, reason: "Storage is not available outside a browser." };
  }

  let serialised: string;

  try {
    serialised = JSON.stringify(value);
  } catch {
    return { ok: false, reason: "That change could not be prepared for saving." };
  }

  try {
    window.localStorage.setItem(key, serialised);
    return { ok: true };
  } catch (error) {
    const quota =
      error instanceof DOMException &&
      (error.name === "QuotaExceededError" ||
        error.name === "NS_ERROR_DOM_QUOTA_REACHED");

    return {
      ok: false,
      reason: quota
        ? "This browser has run out of storage space, so the change was not saved."
        : "This browser would not allow the change to be saved. Private browsing can cause this.",
    };
  }
}

/** Clears one key. Used by the development reset helper, not by the UI. */
export function removeKey(key: StorageKey): void {
  if (typeof window === "undefined") return;

  try {
    window.localStorage.removeItem(key);
  } catch {
    // Nothing useful to do; the caller is a developer tool.
  }
}

/**
 * Clears every key this project owns.
 *
 * Deliberately not wired to a button. Wiping a client demo halfway through is
 * not a thing an interface should offer, so this is exposed on `window` for a
 * developer to call from the console and documented in the completion notes.
 */
export function resetDemoStorage(): void {
  for (const key of Object.values(STORAGE_KEYS)) removeKey(key);
}

if (typeof window !== "undefined") {
  (window as unknown as Record<string, unknown>).krResetDemoStorage =
    resetDemoStorage;
}
