// Signing in to the CMS, via Supabase Auth (GoTrue).
//
// This exports EXACTLY the surface modules/openbase/openbase.tsx exports —
// login, logout, signup, getMe, getToken, requestPasswordReset, resetPassword,
// authedRequest, isLoggedIn, initAuth — so config/opencms--useAuth.ts can pick
// one or the other and no login screen, no guard and no plugin changes.
//
// Two differences worth knowing about, because they change what a person sees:
//
//   1. A new account is emailed a confirmation link before it can sign in.
//      That is a Supabase project setting, not something this file decides;
//      signup() reports it rather than leaving somebody at a login screen
//      wondering why the password they just chose does not work.
//
//   2. Access tokens expire, roughly hourly, and are refreshed automatically
//      by client.ts. getToken() is synchronous because its callers are, so it
//      returns the stored token as-is; anything going through supabaseRequest
//      gets the refreshed one.

import { SUPABASE_ANON_KEY } from "../../config/supabase--anon-key.ts";
import { SUPABASE_URL } from "../../config/supabase--url.ts";
import { readSession, writeSession } from "./client.ts";
import type { SupabaseSession } from "./client";

/** GoTrue's error body. `msg` on older versions, `message` on newer ones. */
type GoTrueError = {
  msg?: string;
  message?: string;
  error_description?: string;
};

async function gotrue(
  path: string,
  body: unknown,
  method: "POST" | "GET" | "PUT" = "POST",
  token?: string
): Promise<unknown> {
  const headers: Record<string, string> = {
    apikey: SUPABASE_ANON_KEY,
    "Content-Type": "application/json",
  };

  if (token) headers.Authorization = `Bearer ${token}`;

  let res: Response;

  try {
    res = await fetch(`${SUPABASE_URL}/auth/v1${path}`, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    throw new Error(
      "Could not reach the sign-in service. Check your connection and try again."
    );
  }

  const text = await res.text();

  let data: unknown = null;
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = text;
    }
  }

  if (!res.ok) {
    const error = (data ?? {}) as GoTrueError;
    const raw = error.msg ?? error.message ?? error.error_description ?? "";

    /* GoTrue's own wording, where it is already the clearest thing to say, and
       a plainer sentence where it is not. "Invalid login credentials" is fine;
       an unexplained 400 is not. */
    throw new Error(
      raw.trim() || `Sign-in failed (error ${res.status}). Please try again.`
    );
  }

  return data;
}

/* ── the surface opencms--useAuth expects ────────────────── */

export async function login(email: string, password: string) {
  const data = (await gotrue("/token?grant_type=password", {
    email,
    password,
  })) as SupabaseSession;

  if (!data?.access_token) {
    throw new Error("Sign-in did not return a session. Please try again.");
  }

  writeSession(data);

  /* Shaped like the openbase reply the login screen already handles, so the
     screen needs no change, with the Supabase session alongside it. */
  return { ...data, token: data.access_token };
}

export function logout(): void {
  const session = readSession();

  /* Told to Supabase so the refresh token is revoked rather than left valid
     until it expires. The local session is cleared either way — a failed
     network call must not leave somebody stuck signed in. */
  if (session?.access_token) {
    void gotrue("/logout", {}, "POST", session.access_token).catch(() => {});
  }

  writeSession(null);
}

export async function getMe() {
  const session = readSession();
  if (!session?.access_token) throw new Error("You are signed out.");

  return gotrue("/user", undefined, "GET", session.access_token);
}

export async function signup(email: string, password: string) {
  const data = (await gotrue("/signup", { email, password })) as SupabaseSession & {
    id?: string;
  };

  /* A project with email confirmation on returns the user but NO session. The
     caller is told, rather than being handed something that looks like a
     successful sign-in and then failing on the next request. */
  if (data?.access_token) {
    writeSession(data);
    return { ...data, token: data.access_token, confirmationRequired: false };
  }

  return { ...data, confirmationRequired: true };
}

export async function requestPasswordReset(email: string) {
  return gotrue("/recover", { email });
}

/**
 * Sets a new password.
 *
 * `token` is the access token from the recovery link Supabase emailed — the
 * link lands on the site with it in the URL fragment, and the reset screen
 * passes it straight through. Supabase has no separate "reset token" endpoint;
 * the recovery link IS a short-lived sign-in.
 */
export async function resetPassword(token: string, password: string) {
  return gotrue("/user", { password }, "PUT", token);
}

export function getToken(): string | null {
  return readSession()?.access_token ?? null;
}

/**
 * A request to the Supabase project with the signed-in user's token.
 *
 * Kept because the openbase surface has it. `path` is relative to the project,
 * e.g. "/rest/v1/leads?select=*".
 */
export async function authedRequest(
  path: string,
  method: string = "GET",
  body?: unknown,
  headers?: HeadersInit
): Promise<unknown> {
  const token = getToken();

  const merged = new Headers(headers);
  merged.set("apikey", SUPABASE_ANON_KEY);
  if (!merged.has("Content-Type")) merged.set("Content-Type", "application/json");
  if (token) merged.set("Authorization", `Bearer ${token}`);

  const res = await fetch(`${SUPABASE_URL}${path}`, {
    method,
    headers: merged,
    body: body === undefined ? undefined : JSON.stringify(body),
  });

  const text = await res.text();

  let data: unknown = text;
  try {
    data = JSON.parse(text);
  } catch {
    /* Not JSON. Returned as text, which is what the openbase version did. */
  }

  if (!res.ok) throw { status: res.status, data };

  return data;
}

export async function isLoggedIn(): Promise<boolean> {
  try {
    await getMe();
    return true;
  } catch {
    return false;
  }
}

/**
 * Called once when the CMS mounts.
 *
 * Verifies the stored session against Supabase rather than trusting that a
 * token in localStorage means anything — it may have been revoked, or the
 * account deleted. A bad one is cleared so the user gets the login screen
 * instead of a CMS that fails every request.
 */
export async function initAuth(): Promise<boolean> {
  if (!readSession()) return false;

  try {
    await getMe();
    return true;
  } catch {
    writeSession(null);
    return false;
  }
}
