// The Application Builder's business rules, as pure functions.
//
// Every one of these takes a document and returns a new document. Nothing here
// touches React, the network or the clock — `now` is always passed in — so the
// rules that actually matter can be tested directly, and the UI is left with
// nothing to decide.
//
// The invariants, in one place:
//   1. At least one live application always exists.
//   2. Exactly one live application is active.
//   3. Deleting is soft: deletedAt is stamped and the record stays put.
//   4. Restoring never silently makes something active.

import type {
  Application,
  ApplicationQuestion,
  ApplicationsDocument,
} from "./types";

/** How long a deleted application stays recoverable. A rule, so it lives here. */
export const TRASH_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

/** Ids are timestamp-prefixed so they sort by age and never collide in a session. */
let counter = 0;
export function makeId(prefix: string, now: number): string {
  counter += 1;
  return `${prefix}-${now}-${counter}`;
}

const iso = (now: number) => new Date(now).toISOString();

/* ── reading ─────────────────────────────────────────────── */

export const isLive = (application: Application) => application.deletedAt === null;

export function liveApplications(doc: ApplicationsDocument): Application[] {
  return doc.applications.filter(isLive);
}

/** Deleted but still inside the recovery window. */
export function trashedApplications(
  doc: ApplicationsDocument,
  now: number
): Application[] {
  return doc.applications.filter(
    (application) =>
      application.deletedAt !== null && !isExpired(application.deletedAt, now)
  );
}

export function daysRemaining(deletedAt: string, now: number): number {
  const elapsed = now - Date.parse(deletedAt);
  const remaining = TRASH_DAYS - Math.floor(elapsed / DAY_MS);
  return Math.max(0, remaining);
}

export function isExpired(deletedAt: string, now: number): boolean {
  return now - Date.parse(deletedAt) >= TRASH_DAYS * DAY_MS;
}

export function activeApplication(doc: ApplicationsDocument): Application | null {
  return liveApplications(doc).find((a) => a.id === doc.activeId) ?? null;
}

/* ── guards ──────────────────────────────────────────────── */

export type Guard = { ok: true } | { ok: false; reason: string };

/**
 * Whether an application may be deleted.
 *
 * The last one may not be, and the caller is expected to show the reason rather
 * than greying out a button and leaving the user to guess.
 */
export function canDelete(doc: ApplicationsDocument, id: string): Guard {
  const live = liveApplications(doc);

  if (!live.some((a) => a.id === id)) {
    return { ok: false, reason: "That application is not available to delete." };
  }

  if (live.length <= 1) {
    return {
      ok: false,
      reason:
        "You need at least one application. Create another application before deleting this one.",
    };
  }

  return { ok: true };
}

/* ── writing ─────────────────────────────────────────────── */

export function createApplication(
  doc: ApplicationsDocument,
  name: string,
  now: number,
  questions: ApplicationQuestion[] = []
): { doc: ApplicationsDocument; id: string } {
  const id = makeId("app", now);
  const application: Application = {
    id,
    name: name.trim() || "Untitled Application",
    questions,
    createdAt: iso(now),
    updatedAt: iso(now),
    deletedAt: null,
  };

  return {
    doc: {
      ...doc,
      // The very first application has to be active; there is nothing else.
      activeId: liveApplications(doc).length === 0 ? id : doc.activeId,
      applications: [...doc.applications, application],
    },
    id,
  };
}

export function renameApplication(
  doc: ApplicationsDocument,
  id: string,
  name: string,
  now: number
): ApplicationsDocument {
  return mapApplication(doc, id, (application) => ({
    ...application,
    name: name.trim() || application.name,
    updatedAt: iso(now),
  }));
}

/**
 * Sets the active application.
 *
 * Ignored for anything deleted or unknown — activating a trashed application
 * would leave the public form pointing at something the CMS does not show.
 */
export function setActive(
  doc: ApplicationsDocument,
  id: string
): ApplicationsDocument {
  if (!liveApplications(doc).some((a) => a.id === id)) return doc;
  return { ...doc, activeId: id };
}

/**
 * Soft delete.
 *
 * `nextActiveId` is required when deleting the active one, because picking a
 * successor is the user's decision, not a rule we can guess. Nothing is removed
 * from the array, so Trash and Restore work on the real record.
 */
export function deleteApplication(
  doc: ApplicationsDocument,
  id: string,
  now: number,
  nextActiveId?: string
): ApplicationsDocument {
  const guard = canDelete(doc, id);
  if (!guard.ok) return doc;

  const deleted = mapApplication(doc, id, (application) => ({
    ...application,
    deletedAt: iso(now),
    updatedAt: iso(now),
  }));

  if (doc.activeId !== id) return deleted;

  const remaining = liveApplications(deleted);
  const chosen =
    nextActiveId && remaining.some((a) => a.id === nextActiveId)
      ? nextActiveId
      : remaining[0]?.id;

  return chosen ? { ...deleted, activeId: chosen } : deleted;
}

/** Restores from trash. Never changes which application is active. */
/**
 * What a bulk delete would actually do.
 *
 * MTC-KRP-038 brought the Properties CMS's select-several-then-delete mode
 * here, and it meets a rule Properties does not have: a site must always keep
 * at least one application, because the public form has to point at something.
 * So a selection of every application cannot be honoured in full.
 *
 * Rather than silently dropping one and leaving the user to notice, this
 * reports the split up front so the interface can say so BEFORE the confirm.
 * `blocked` is the applications that would have to stay.
 */
export type BulkDeletePlan = {
  /** Ids that will actually be deleted. */
  deleting: string[];
  /** Ids that cannot be, because something must survive. */
  blocked: string[];
  /** Null when the whole selection can go. */
  reason: string | null;
};

export function planBulkDelete(
  doc: ApplicationsDocument,
  ids: string[]
): BulkDeletePlan {
  const live = liveApplications(doc);
  const liveIds = new Set(live.map((application) => application.id));

  /* Anything already deleted, or not a real application, is not part of this. */
  const wanted = ids.filter((id) => liveIds.has(id));

  if (wanted.length === 0) {
    return { deleting: [], blocked: [], reason: "Nothing is selected." };
  }

  if (wanted.length >= live.length) {
    /* Keep the last one standing. The one kept is the one at the end of the
       list rather than an arbitrary pick, so the choice is at least
       predictable from what the user is looking at. */
    const keep = wanted[wanted.length - 1];

    return {
      deleting: wanted.filter((id) => id !== keep),
      blocked: [keep],
      reason:
        "You need to keep at least one application, so the last one will stay.",
    };
  }

  return { deleting: wanted, blocked: [], reason: null };
}

/**
 * Deletes several applications at once.
 *
 * Applied one at a time through `deleteApplication` rather than reimplemented,
 * so every rule that function enforces — the keep-one guard, moving `activeId`
 * off a deleted application — holds here too without a second copy that can
 * drift. Each step re-reads the document it has just produced, so reassigning
 * the active application always lands on something that survives.
 */
export function deleteApplications(
  doc: ApplicationsDocument,
  ids: string[],
  now: number
): ApplicationsDocument {
  return planBulkDelete(doc, ids).deleting.reduce(
    (current, id) => deleteApplication(current, id, now),
    doc
  );
}

export function restoreApplication(
  doc: ApplicationsDocument,
  id: string,
  now: number
): ApplicationsDocument {
  const application = doc.applications.find((a) => a.id === id);
  if (!application || application.deletedAt === null) return doc;
  if (isExpired(application.deletedAt, now)) return doc;

  return mapApplication(doc, id, (current) => ({
    ...current,
    deletedAt: null,
    updatedAt: iso(now),
  }));
}

/* ── questions ───────────────────────────────────────────── */

export function addQuestion(
  doc: ApplicationsDocument,
  applicationId: string,
  question: ApplicationQuestion,
  now: number
): ApplicationsDocument {
  return mapApplication(doc, applicationId, (application) => ({
    ...application,
    questions: [...application.questions, question],
    updatedAt: iso(now),
  }));
}

export function updateQuestion(
  doc: ApplicationsDocument,
  applicationId: string,
  questionId: string,
  patch: Partial<ApplicationQuestion>,
  now: number
): ApplicationsDocument {
  return mapApplication(doc, applicationId, (application) => ({
    ...application,
    questions: application.questions.map((question) =>
      question.id === questionId ? { ...question, ...patch } : question
    ),
    updatedAt: iso(now),
  }));
}

export function deleteQuestion(
  doc: ApplicationsDocument,
  applicationId: string,
  questionId: string,
  now: number
): ApplicationsDocument {
  return mapApplication(doc, applicationId, (application) => ({
    ...application,
    questions: application.questions.filter((q) => q.id !== questionId),
    updatedAt: iso(now),
  }));
}

/**
 * Moves a question one place up or down.
 *
 * A swap rather than a splice, and a no-op at the ends, so the buttons can stay
 * disabled there without the rule depending on the UI having done so.
 */
export function moveQuestion(
  doc: ApplicationsDocument,
  applicationId: string,
  questionId: string,
  direction: "up" | "down",
  now: number
): ApplicationsDocument {
  return mapApplication(doc, applicationId, (application) => {
    const index = application.questions.findIndex((q) => q.id === questionId);
    if (index === -1) return application;

    const target = direction === "up" ? index - 1 : index + 1;
    if (target < 0 || target >= application.questions.length) return application;

    const questions = [...application.questions];
    [questions[index], questions[target]] = [questions[target], questions[index]];

    return { ...application, questions, updatedAt: iso(now) };
  });
}

/* ── internal ────────────────────────────────────────────── */

function mapApplication(
  doc: ApplicationsDocument,
  id: string,
  change: (application: Application) => Application
): ApplicationsDocument {
  return {
    ...doc,
    applications: doc.applications.map((application) =>
      application.id === id ? change(application) : application
    ),
  };
}
