// The Application Builder, backed by Supabase.
//
// Implements the SAME ApplicationsApi the demo and worker adapters do, so
// ApplyView, the Builder, the Trash and the walkthrough are all unchanged and
// cannot tell which one they are holding.

import { PATH } from "../../contracts/getApplications.ts";
import { parseDocument, seedDocument } from "../gh-apply/applicationsStore.ts";
import type { ApplicationsApi, LoadResult } from "../gh-apply/applicationsStore";
import type { ApplicationsDocument } from "../gh-apply/types";
import { loadDocument, saveDocument } from "./documents.ts";

export const supabaseApplicationsApi: ApplicationsApi = {
  async load(): Promise<LoadResult> {
    const result = await loadDocument<unknown>(PATH);

    if (result.ok && result.data) {
      const parsed = parseDocument(result.data);
      /* A row that exists but is the wrong shape falls through to the seed
         rather than handing the Builder something it cannot render. */
      if (parsed) return { doc: parsed, remote: true, source: "remote" };
    }

    /* No row yet, or unreadable. The site starts from its bundled application,
       which is the correct first-run state rather than an error. */
    return { doc: seedDocument(Date.now()), remote: false, source: "seed" };
  },

  async save(doc: ApplicationsDocument): Promise<void> {
    const result = await saveDocument(PATH, doc);

    /* Thrown, because that is what every caller of this interface already
       expects a failed save to do. The message is the one the client wrote. */
    if (!result.ok) throw new Error(result.error.message);
  },
};
